files = fs_list('orders')
orders = []
skus = []
for f in files:
    data = fs_read_json('orders/' + f)
    orders.append([f, data['sku'], data['qty']])
    if data['sku'] not in skus:
        skus.append(data['sku'])
stock = {}
for sku in skus:
    stock[sku] = warehouse_stock(sku)['on_hand']
shortfalls = []
for f, sku, qty in orders:
    if qty > stock[sku]:
        shortfalls.append(f)
shortfalls = sorted(shortfalls)
fs_write('shortfall.txt', ','.join(shortfalls))
print(len(shortfalls))

files = fs_list('orders')
orders = []
for f in files:
    orders.append((f, fs_read_json('orders/' + f)))
skus = []
seen = {}
for f, o in orders:
    sku = o['sku']
    if sku not in seen:
        seen[sku] = True
        skus.append(sku)
stock = {}
for sku in skus:
    stock[sku] = warehouse_stock(sku)['on_hand']
short = []
for f, o in orders:
    if o['qty'] > stock[o['sku']]:
        short.append(f)
short = sorted(short)
fs_write('shortfall.txt', ','.join(short))
print(len(short))
